begin;
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000086');
insert into auth.sessions(id,user_id,created_at,updated_at) values ('11000000-0000-4000-8000-000000000086','10000000-0000-4000-8000-000000000086',now(),now()),('11000000-0000-4000-8000-000000000087','10000000-0000-4000-8000-000000000086',now(),now());
insert into public.ns_organizations(id,display_name,business_mode) values ('20000000-0000-4000-8000-000000000086','QA delivery','solo');
insert into public.ns_accounts(id,auth_user_id,login_id,auth_alias,password_change_required) values ('50000000-0000-4000-8000-000000000086','10000000-0000-4000-8000-000000000086','NS-QA86','ns-qa86@example.invalid',false);
insert into public.ns_members(id,org_id,account_id,display_name,role_code) values ('60000000-0000-4000-8000-000000000086','20000000-0000-4000-8000-000000000086','50000000-0000-4000-8000-000000000086','QA','promoter');
insert into public.ns_devices(id,account_id,installation_id,platform,session_id) values ('70000000-0000-4000-8000-000000000086','50000000-0000-4000-8000-000000000086','qa86','android','11000000-0000-4000-8000-000000000086'),('70000000-0000-4000-8000-000000000087','50000000-0000-4000-8000-000000000086','qa87','android','11000000-0000-4000-8000-000000000087');
insert into public.ns_notification_outbox(id,org_id,recipient_member_id,channel,event_code,idempotency_key) values ('80000000-0000-4000-8000-000000000086','20000000-0000-4000-8000-000000000086','60000000-0000-4000-8000-000000000086','push','QA','qa-device-delivery');
do $qa$ declare o uuid:='20000000-0000-4000-8000-000000000086'; m uuid:='60000000-0000-4000-8000-000000000086'; n uuid:='80000000-0000-4000-8000-000000000086'; t1 uuid; t2 uuid; cl uuid; cl2 uuid; summary jsonb;
begin
 t1:=public.ns_register_bound_push_token(o,m,'70000000-0000-4000-8000-000000000086','11000000-0000-4000-8000-000000000086','android',repeat('x',64),repeat('i',16),repeat('8',64),'8888');
 t2:=public.ns_register_bound_push_token(o,m,'70000000-0000-4000-8000-000000000087','11000000-0000-4000-8000-000000000087','android',repeat('y',64),repeat('j',16),repeat('9',64),'9999');
 select claim_token into cl from public.ns_claim_notification_batch(100) where id=n;
 if (select count(*) from public.ns_pending_push_targets(n,cl))<>2 then raise exception 'TARGET_COUNT'; end if;
 if public.ns_record_push_device_outcome(n,gen_random_uuid(),t1,'accepted','invalid',null) then raise exception 'STALE_CLAIM_ACCEPTED'; end if;
 if not public.ns_record_push_device_outcome(n,cl,t1,'accepted','qa-reference',null) then raise exception 'FIRST_OUTCOME'; end if;
 if (select count(*) from public.ns_pending_push_targets(n,cl))<>1 then raise exception 'FIRST_TARGET_NOT_EXCLUDED'; end if;
 if public.ns_fail_notification_send(n,cl,'FCM_TEMPORARY_UNAVAILABLE',true)<>'pending' then raise exception 'RETRY_NOT_PENDING'; end if;
 update public.ns_notification_outbox set scheduled_at=now()-interval '1 second' where id=n;
 select claim_token into cl2 from public.ns_claim_notification_batch(100) where id=n;
 if cl2=cl or (select count(*) from public.ns_pending_push_targets(n,cl2))<>1 then raise exception 'RETRY_TARGETS'; end if;
 if not public.ns_record_push_device_outcome(n,cl2,t2,'rejected',null,'UNREGISTERED') then raise exception 'SECOND_OUTCOME'; end if;
 summary:=public.ns_push_delivery_summary(n,cl2);
 if (summary->>'accepted')::int<>1 or (summary->>'rejected')::int<>1 or (summary->>'pending')::int<>0 or summary->>'provider_reference'<>'qa-reference' then raise exception 'DELIVERY_SUMMARY'; end if;
 if not public.ns_finish_notification_send(n,cl2,summary->>'provider_reference') then raise exception 'FINALIZE'; end if;
 if (select count(*) from public.ns_notification_inbox where notification_id=n)<>1 then raise exception 'INBOX_COUNT'; end if;
end $qa$;
rollback;
select 'PASS: multi-device receipts, scoped lease, retry excludes terminal device, one inbox' result;